mapper.select:
select count(m.instance_id) from
(select t.instance_id from t_cruise_nonhomologous_point_instance t where t.robot_instance_id = #{robotInstanceId, jdbcType=BIGINT} and t.cruise_type = #{cruiseType, jdbcType=INTEGER}

    union
    select r.instance_id from t_cruise_nonhomologous_point_instance r where r.video_preset_id = #{videoPresetId, jdbcType=BIGINT} and r.cruise_type = #{cruiseType, jdbcType=INTEGER}

) m

select a.warn_id, a.instance_id, a.warn_content, a.warn_time, d.device_mete_id, e.custom_id, e.device_id, d.mete_name as device_mete_name, e.custom_name, e.device_name, e.device_type, k.dict_note as device_type_name, a.warn_type, n.warn_level, j.camera_name, h.robot_name from t_cruise_nonhomologous_warn a inner join t_cruise_nonhomologous_point_instance n on n.instance_id = a.instance_id left join t_cruise_point_instance b on b.instance_id = n.robot_instance_id left join t_cruise_point_instance c on c.instance_id = n.video_preset_id left join t_std_devicemete d on d.device_mete_id = n.device_mete_id left join t_std_device e on e.custom_id = d.custom_id and e.device_id = d.device_id left join t_robot_inspection g on g.inspection_id = b.cruise_id left join t_robot_info h on h.robot_id = g.robot_id left join t_camera_preset i on i.preset_id = c.cruise_id left join t_camera_info j on j.camera_id = i.camera_id left join t_dict_business k on k.dict_code = e.device_type where 1 = 1 and a.instance_id = #{instanceId, jdbcType=BIGINT} and f.device_name = #{deviceType, jdbcType=INTEGER} and e.device_name like concat('%',#{deviceName, jdbcType=VARCHAR},'%') and d.mete_name like concat('%',#{deviceMeteName, jdbcType=VARCHAR},'%') and a.warn_type = #{warnType, jdbcType=INTEGER}
and a.warn_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
union all select a.warn_id, a.instance_id, a.warn_content, a.warn_time, m.device_mete_id, m.custom_id, m.device_id, m.device_mete_name, m.custom_name, m.device_name, m.device_type, m.device_type_name, a.warn_type, 2 as warn_level, null as camera_name, m.robot_name from t_cruise_nonhomologous_warn a INNER join (select n.warn_id, GROUP_CONCAT(distinct d.device_mete_id) as device_mete_id, GROUP_CONCAT(distinct e.custom_id) as custom_id, GROUP_CONCAT(distinct e.device_id) as device_id, GROUP_CONCAT(distinct d.mete_name) as device_mete_name, GROUP_CONCAT(distinct e.custom_name) as custom_name, GROUP_CONCAT(distinct e.device_name) as device_name, GROUP_CONCAT(distinct e.device_type) as device_type, GROUP_CONCAT(distinct k.dict_note) as device_type_name, GROUP_CONCAT(distinct h.robot_name) as robot_name from t_cruise_nonhomologous_warn_inspection n left join t_cruise_point_instance b on b.instance_id = n.inspection_id left join t_std_devicemete d on d.device_mete_id = b.device_mete_id left join t_std_device e on e.custom_id = b.custom_id and e.device_id = b.device_id left join t_robot_inspection g on g.inspection_id = b.cruise_id left join t_robot_info h on h.robot_id = g.robot_id left join t_dict_business k on k.dict_code = e.device_type GROUP BY n.warn_id) m on m.warn_id = a.warn_id where 1=1 and a.instance_id = #{instanceId, jdbcType=BIGINT} and m.device_name = #{deviceType, jdbcType=INTEGER} and m.device_name like concat('%',#{deviceName, jdbcType=VARCHAR},'%') and m.mete_name like concat('%',#{deviceMeteName, jdbcType=VARCHAR},'%') and a.warn_type = #{warnType, jdbcType=INTEGER}
and a.warn_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
